package com.northstar.crm.ui;
import com.northstar.crm.domain.*;import com.northstar.crm.security.ActorResolver;import com.northstar.crm.service.EscalationService;import com.northstar.crm.service.IntegrationService;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.checkbox.Checkbox;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.TextArea;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;import java.time.ZoneId;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Route(value="escalations/:id",layout=MainLayout.class)@PageTitle("Escalation · Northstar")@PermitAll public class EscalationDetailView extends VerticalLayout implements BeforeEnterObserver {
 private final EscalationService service;private final IntegrationService assistants;private final ActorResolver actors;private UUID id;private Escalation escalation;private final VerticalLayout timeline=new VerticalLayout();
 public EscalationDetailView(EscalationService s,IntegrationService i,ActorResolver a){service=s;assistants=i;actors=a;setPadding(false);setSizeFull();}
 @Override public void beforeEnter(BeforeEnterEvent e){try{id=UUID.fromString(e.getRouteParameters().get("id").orElseThrow());escalation=service.getAuthorized(id);render();}catch(Exception x){e.rerouteToError(org.springframework.security.access.AccessDeniedException.class,"Request unavailable");}}
 private void render(){removeAll();var back=new RouterLink("← Escalation queue",EscalationsView.class);var head=new Div(new Span(UiKit.human(escalation.getSeverity())+" PRIORITY"),new H1(escalation.getSubject()),new Paragraph(escalation.getCustomerSummary()),UiKit.badge(escalation.getStatus()));head.addClassName("case-head");var next=new ComboBox<EscalationStatus>("Move status");next.setItems(EscalationService.ALLOWED_TRANSITIONS.getOrDefault(escalation.getStatus(),Set.of()));next.addValueChangeListener(e->{if(e.getValue()!=null)try{escalation=service.transition(id,e.getValue());render();UiKit.success("Escalation status updated");}catch(Exception ex){UiKit.error(ex);}});var workflow=new HorizontalLayout(next);workflow.addClassName("workflow-bar");var reply=new TextArea("Add an update");reply.setPlaceholder("Share clear next steps…");reply.setWidthFull();reply.setMaxLength(4000);var internal=new Checkbox("Internal note—hidden from customers");internal.setVisible(actors.current().getRole()!=Role.CUSTOMER_CONTACT);var send=UiKit.primary("Post update",e->{try{service.addComment(id,reply.getValue(),internal.getValue());reply.clear();internal.clear();loadTimeline();UiKit.success("Update posted");}catch(Exception ex){UiKit.error(ex);}});var composer=new VerticalLayout(reply,internal,send);composer.addClassName("panel");var ask=new TextArea("Ask copilot");ask.setPlaceholder("Tell the desk model which move to apply");ask.setWidthFull();ask.setMaxLength(400);var run=UiKit.primary("Run copilot triage",e->{try{assistants.triageEscalation(id,ask.getValue());escalation=service.getAuthorized(id);render();UiKit.success("Copilot move applied");}catch(Exception ex){UiKit.error(ex);}});var copilot=new VerticalLayout(ask,run);copilot.addClassName("panel");loadTimeline();var activity=new VerticalLayout(new H2("Conversation & internal timeline"),timeline);activity.addClassName("panel");add(UiKit.page("ESCALATION RECORD",escalation.getSubject(),"Customer-visible replies and restricted internal notes share one accountable timeline.",back,head,workflow,copilot,composer,activity));}
 private void loadTimeline(){timeline.removeAll();var values=service.comments(id);if(values.isEmpty()){timeline.add(new Paragraph("No updates yet. Add the first clear next step."));return;}values.forEach(c->{var time=new Span(c.getCreatedAt().atZone(ZoneId.systemDefault()).toString());time.addClassName("timeline-time");var item=new Div(new Span(c.isInternalOnly()?"INTERNAL NOTE":"CUSTOMER UPDATE"),new Paragraph(c.getBody()),time);item.addClassNames("timeline-item",c.isInternalOnly()?"internal":"visible");timeline.add(item);});}
}
